<?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<div class="inlineActions"><a class="button secondary" href="/admin/accounts.php">← Accounts</a><a class="button secondary" href="/admin/billing.php">Billing & Stripe</a><a class="button secondary" href="/admin/usage.php">AI Usage</a></div>
<section class="adminAccountSummaryGrid"><article class="card"><span class="meta">Account status</span><strong><?=h((string)$account['status'])?></strong></article><article class="card"><span class="meta">Subscription</span><strong><?=h((string)$account['subscription_status'])?></strong></article><article class="card"><span class="meta">Package</span><strong><?=h((string)$account['package_name'])?></strong><small><?=h((string)($account['billing_source']??'manual'))?> billing</small></article><article class="card"><span class="meta">Members</span><strong><?=h((string)count($members))?> / <?=h((string)$ent['values']['member_limit'])?></strong></article><article class="card"><span class="meta">AI tokens used</span><strong><?=$usage?h(number_format((int)$usage['used_tokens'])):'—'?></strong></article><article class="card"><span class="meta">AI tokens remaining</span><strong><?=$usage?($usage['remaining_tokens']===null?'Uncapped':h(number_format((int)$usage['remaining_tokens']))):'—'?></strong></article></section>
