<article class="card"><span class="eyebrow">PACKAGE</span><h2>Commercial package</h2><p><strong><?=h((string)$account['package_name'])?></strong><br><span class="meta">Period <?=h((string)$account['period_start'])?> → <?=h((string)$account['period_end'])?></span></p><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)$account['public_id'])?>"><input type="hidden" name="action" value="package"><label>Package<select name="package_id"><?php foreach($packages as $p):?><option value="<?=h((string)$p['public_id'])?>" <?=$p['public_id']===$account['package_public_id']?'selected':''?>><?=h((string)$p['name'])?></option><?php endforeach?></select></label><label>Reason<textarea name="reason" rows="2" required></textarea></label><button>Change package</button></form></article></section>
<section class="card"><div class="sectionHeadWeb"><div><span class="eyebrow">MEMBERSHIP</span><h2>Account members</h2></div><span class="badge">Effective limit <?=h((string)$ent['values']['member_limit'])?></span></div><form method="post" class="adminMemberAddForm"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)$account['public_id'])?>"><input type="hidden" name="action" value="add_member"><label>User<input name="user_identifier" required placeholder="username, email or user ID"></label><label>Role<select name="account_role"><option value="member">Member</option><option value="admin">Account admin</option></select></label><label>Reason<input name="reason" required maxlength="500"></label><button>Add member</button></form>
<div class="tableWrap"><table><thead><tr><th>User</th><th>Role</th><th>Joined</th><th>Administration</th></tr></thead><tbody><?php foreach($members as $m):?><tr><td><strong><?=h((string)$m['display_name'])?></strong><div class="meta">@<?=h((string)$m['username'])?> · <?=h((string)$m['email'])?></div></td><td><?=h((string)$m['account_role'])?></td><td><?=h((string)$m['joined_at'])?></td><td><?php if($m['account_role']!=='owner'):?><form method="post" class="adminMemberActionForm"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)$account['public_id'])?>"><input type="hidden" name="action" value="member_role"><input type="hidden" name="user_id" value="<?=h((string)$m['user_id'])?>"><select name="account_role"><option value="member" <?=$m['account_role']==='member'?'selected':''?>>Member</option><option value="admin" <?=$m['account_role']==='admin'?'selected':''?>>Account admin</option></select><input name="reason" required placeholder="Reason"><button>Update role</button></form><form method="post" class="adminMemberActionForm"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)$account['public_id'])?>"><input type="hidden" name="action" value="remove_member"><input type="hidden" name="user_id" value="<?=h((string)$m['user_id'])?>"><input name="reason" required placeholder="Removal reason"><button class="button secondary">Remove</button></form><?php if($account['account_type']!=='personal'):?><form method="post" class="adminMemberActionForm"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)$account['public_id'])?>"><input type="hidden" name="action" value="transfer_owner"><input type="hidden" name="user_id" value="<?=h((string)$m['user_id'])?>"><input name="reason" required placeholder="Transfer reason"><button class="button secondary">Make owner</button></form><?php endif?><?php else:?><span class="meta">Owner is protected. Transfer ownership first for organization accounts.</span><?php endif?></td></tr><?php endforeach?></tbody></table></div></section>
